import{_ as t,o as e,c as r,ag as i}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"确认安装成功","description":"按清单确认安装完成、两个入口可登录，以及页面刷新和退出正常。","frontmatter":{"title":"确认安装成功","description":"按清单确认安装完成、两个入口可登录，以及页面刷新和退出正常。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/verify.md","filePath":"zh/安装运维/确认安装成功.md"}'),o={name:"zh/installation/verify.md"};function l(d,a,n,h,s,c){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="确认安装成功" tabindex="-1">确认安装成功 <a class="header-anchor" href="#确认安装成功" aria-label="Permalink to &quot;确认安装成功&quot;">​</a></h1><p>装好之后，从终端到浏览器检查一次。准备安装结果中的两个地址及对应账号。</p><p>本页用于 Ubuntu 24 上的 v1.0 安装和基本访问检查，其他系统尚未测试。实际工程的采集、计算、报警等功能仍需分别核对。</p><h2 id="_1-确认终端真的完成了" tabindex="-1">1. 确认终端真的完成了 <a class="header-anchor" href="#_1-确认终端真的完成了" aria-label="Permalink to &quot;1. 确认终端真的完成了&quot;">​</a></h2><ul><li>[ ] 14 个阶段均已完成，最后是“检查服务状态”。</li><li>[ ] 出现 <strong>“InduFrame 中心安装完成。”</strong>。</li><li>[ ] 安装命令没有报错并正常结束。</li><li>[ ] 已记下公共入口、管理入口和本次日志路径。</li></ul><p>安装人员核查退出状态时应为 <code>0</code>。只看到 <code>14/14</code>、安装仍在等待，或网页偶尔能打开，都不算完成。</p><h2 id="_2-用平台账号检查管理入口" tabindex="-1">2. 用平台账号检查管理入口 <a class="header-anchor" href="#_2-用平台账号检查管理入口" aria-label="Permalink to &quot;2. 用平台账号检查管理入口&quot;">​</a></h2><p>打开终端给出的<strong>管理入口</strong>，页面标题应为“平台管理员登录”。</p><p>用安装时设置的平台超级管理员登录，打开“组织管理”，确认能看到组织列表。全新安装时，按<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>为默认组织管理员设置密码。</p><p>保留数据后的重装使用原平台账号，不要重新初始化或覆盖已有账号。</p><h2 id="_3-用组织账号检查公共入口" tabindex="-1">3. 用组织账号检查公共入口 <a class="header-anchor" href="#_3-用组织账号检查公共入口" aria-label="Permalink to &quot;3. 用组织账号检查公共入口&quot;">​</a></h2><p>打开终端给出的<strong>公共入口</strong>，页面标题应为“登录工作台”。</p><ol><li>出现“选择组织”时选择自己的组织。</li><li>用该组织的管理员账号和密码登录。</li><li>确认进入工作台，并能打开“工程管理”。</li><li>刷新页面，确认仍可正常访问。</li></ol><p>这一步使用组织账号，不是安装时设置的平台密码。只有一个可登录组织时会自动选中，不显示选择框。</p><h2 id="_4-检查退出登录" tabindex="-1">4. 检查退出登录 <a class="header-anchor" href="#_4-检查退出登录" aria-label="Permalink to &quot;4. 检查退出登录&quot;">​</a></h2><p>从用户菜单选择“退出登录”，确认回到登录页。再次访问需要登录的页面时，应要求重新登录。</p><h2 id="_5-保存交接信息" tabindex="-1">5. 保存交接信息 <a class="header-anchor" href="#_5-保存交接信息" aria-label="Permalink to &quot;5. 保存交接信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>给谁</th><th>交接什么</th></tr></thead><tbody><tr><td>服务器维护人员</td><td>完整原安装包位置、实际程序目录、安装日志路径</td></tr><tr><td>平台超级管理员</td><td>管理入口、平台账号及默认组织设置结果</td></tr><tr><td>组织管理员</td><td>公共入口、组织名称和组织管理员账号</td></tr></tbody></table><p>密码通过安全方式单独交接，不放入截图、普通日志或公开问题记录。</p><h2 id="检查未通过时" tabindex="-1">检查未通过时 <a class="header-anchor" href="#检查未通过时" aria-label="Permalink to &quot;检查未通过时&quot;">​</a></h2><p>记下卡在哪一步、发生时间和完整提示，查<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>。不要用反复重装处理登录问题，也不要仅凭一个入口能打开就认定全部检查通过。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>基本检查完成后，阅读<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>。当前版本和系统范围见<a href="/induframe-docs/zh/releases/">版本记录</a>和<a href="/induframe-docs/zh/reference/system-requirements.html">系统与安装要求</a>。</p>',23)])])}const u=t(o,[["render",l]]);export{_ as __pageData,u as default};
